import"./modulepreload-polyfill-B5Qt9EMX.js";import{m as i}from"./foundation-module-BgS6mBLm.js";import{h as s,p as t,i as e}from"./content-helpers-BfuPXrd1.js";const a='<div class="fm-risk-grid" role="img" aria-label="A four-part risk matrix labeled high impact low probability, high impact high probability, low impact low probability, and low impact high probability"><span>High impact<br>Low probability</span><span class="warn">High impact<br>High probability</span><span>Low impact<br>Low probability</span><span>Low impact<br>High probability</span></div>',r='<section class="fm-block"><p class="fm-label">Fixed scenarios</p><h2>Analyze these six risks</h2><div class="fm-table-wrap"><table><thead><tr><th>ID</th><th>Scenario evidence</th></tr></thead><tbody><tr><td>R1</td><td>A shared attendance account uses school123. Two unknown login attempts appeared this week. The account contains student attendance records.</td></tr><tr><td>R2</td><td>Staff receive fake school-login messages every week. Multi-factor authentication is enabled on staff accounts.</td></tr><tr><td>R3</td><td>An offline practice laptop stores no personal data and is reset at the end of every day.</td></tr><tr><td>R4</td><td>A library computer has missed verified security updates for six months and downloads email attachments.</td></tr><tr><td>R5</td><td>The public school website had one short service outage last year. It publishes announcements but stores no student records.</td></tr><tr><td>R6</td><td>A project folder has no backup. Students accidentally delete or overwrite a file about once each month.</td></tr></tbody></table></div><p class="fm-note">Keep each scenario ID beside its rating. Your exported report must show which facts supported each decision.</p></section>',o={id:"MOD-CYBERSECURITY-RISK-01",slug:"cybersecurity-risk",version:"0.1.0",storageKey:"mod-cybersecurity-risk-01-v0.1.0",mark:"C9",shortTitle:"Cybersecurity risk",title:"Cybersecurity Threats and Risk Decisions",gradeLabel:"Grade 9 Technology",classes:["9A","9B"],sections:[{id:"start",short:"Start",title:"Choose protection from evidence",summary:"Learn the threat vocabulary, rate probability and impact, then recommend a protection.",minutes:5,html:`<section class="fm-opening"><div><p class="fm-label">Goal</p><h2>Risk is not the same as fear</h2><p>A useful decision names the asset, threat, and vulnerability. It then uses evidence to estimate probability and impact before choosing a protection.</p><p>Work through each Learn page before its matching Practice page.</p></div>${a}</section>`},{id:"threat-learn",short:"Learn threats",title:"Separate assets, threats, vulnerabilities, and protections",summary:"Learn the vocabulary and common threat types needed for the scenario practice.",minutes:18,html:'<section class="fm-block"><p class="fm-label">Learn</p><h2>Name each part of a security scenario</h2><div class="fm-concept-grid"><div><h3>Asset</h3><p>Data, account, device, or service that has value.</p></div><div><h3>Threat</h3><p>Something that could cause harm to an asset.</p></div><div><h3>Vulnerability</h3><p>A weakness the threat could use.</p></div><div><h3>Protection</h3><p>An action or control that lowers probability or impact.</p></div></div><div class="fm-table-wrap"><table><thead><tr><th>Threat</th><th>How it works</th><th>Useful clue</th></tr></thead><tbody><tr><td>Phishing</td><td>A deceptive message or page tries to steal information.</td><td>Impersonation, urgency, or a false login link</td></tr><tr><td>Brute-force attack</td><td>An attacker tries many password combinations.</td><td>Repeated failed logins</td></tr><tr><td>Malware</td><td>Harmful software damages, disrupts, spies, or takes control.</td><td>An unsafe program, attachment, or download</td></tr><tr><td>DDoS</td><td>Many devices flood a service with traffic so normal users cannot reach it.</td><td>A service becomes unavailable under abnormal traffic</td></tr></tbody></table></div><p><strong>Malware families:</strong> a virus attaches to files or programs, a worm can spread across networks, a trojan pretends to be safe software, and ransomware locks data or systems.</p><p class="fm-note">A firewall filters network traffic. Verified updates repair known software weaknesses. MFA adds another login proof. Backups reduce the harm of data loss. Each protection solves a different part of a risk.</p></section>'},t("threat-practice","Threat practice","Practice identifying cyber threats","Complete five scenarios using the threat vocabulary from the previous lesson.",[e("Phishing message","A message imitates the school login page and asks for a password. What is the threat?",["Phishing","File compression","Data visualization"],0,"Identify phishing","Phishing uses deceptive messages or pages to steal information.","Look for impersonation and a request for credentials."),e("Password attempts","A login log shows hundreds of password guesses against one account. What is the threat?",["Brute-force attack","Image compression","A spreadsheet formula"],0,"Identify brute force","A brute-force attack tries many password combinations.","Look for repeated password guesses."),e("Fake safe program","A download claims to be a free game but installs harmful software. Which malware family best matches?",["Trojan","Firewall","Backup"],0,"Identify a trojan","A trojan pretends to be wanted or safe software.","The disguise is the main clue."),e("Flooded website","Thousands of devices send traffic until the school site becomes unavailable. What is the threat?",["DDoS","Phishing","RGB"],0,"Identify DDoS","A DDoS attack floods a service so normal users cannot reach it.","Focus on abnormal traffic and loss of availability."),e("Filter network traffic","Which protection can allow or block network traffic using security rules?",["Firewall","Color depth","Chart label"],0,"Identify a firewall","A firewall filters network traffic according to rules.","Choose the control that works on network connections.")]),{id:"risk-learn",short:"Learn risk",title:"Rate probability and impact separately",summary:"Learn how scenario facts support a position on a risk matrix.",minutes:15,html:`<section class="fm-block"><p class="fm-label">Learn</p><h2>Probability asks how likely. Impact asks how harmful.</h2>${a}<p>Use the evidence supplied with the scenario. A dramatic threat is not automatically likely, and a frequent event is not automatically harmful.</p><div class="fm-concept-grid"><div><h3>Probability evidence</h3><p>Frequency, exposure, existing controls, and known attempts.</p></div><div><h3>Impact evidence</h3><p>Data sensitivity, number of users, downtime, cost, and recovery difficulty.</p></div></div><div class="fm-table-wrap"><table><thead><tr><th>Scenario fact</th><th>Axis</th><th>Reason</th></tr></thead><tbody><tr><td>Five similar attempts this month</td><td>Probability</td><td>The count shows repeated exposure.</td></tr><tr><td>The folder contains private student records</td><td>Impact</td><td>Exposure could harm students.</td></tr><tr><td>A tested offline backup exists</td><td>Impact</td><td>Recovery may reduce lasting damage.</td></tr></tbody></table></div><p class="fm-note">A rating needs a fact and a reason. "It feels dangerous" is not evidence.</p></section>`},t("risk-practice","Risk practice","Practice probability-impact ratings","Complete five activities using the matrix and scenario evidence.",[e("Frequent phishing","Staff receive fake login messages weekly, but MFA is enabled. Which fact most directly raises probability?",["Weekly attempts","MFA is enabled","The school logo is blue"],0,"Use frequency evidence","Weekly attempts show repeated exposure to the threat.","Probability depends partly on how often the threat is encountered."),e("Sensitive records","A system stores medical accommodation records. Which factor most directly raises impact?",["Data sensitivity","Monitor size","Number of icons"],0,"Use impact evidence","Exposure of sensitive records could harm students and violate privacy duties.","Impact concerns the consequences if the event occurs."),e("Low exposure","An offline practice laptop contains no personal data and is reset daily. What is the best impact rating for data theft?",["Low","Automatically high","Impossible to discuss"],0,"Rate the stated asset","The device contains little lasting data, so the described impact is low.","Use the scenario facts, not a general fear of theft."),e("High priority","Which risk normally deserves attention first?",["High probability and high impact","Low probability and low impact","A risk with no evidence"],0,"Prioritize a risk matrix","High probability and high impact combine frequent occurrence with serious harm.","Consider both axes together."),e("Explain a rating","Which statement gives evidence for a probability rating?",["Probability is high because five similar attempts were recorded this month","It feels dangerous","Cybersecurity is important"],0,"Use scenario evidence","The count and time period support the probability judgment.","A justification should cite a fact from the scenario.")]),{id:"protection-learn",short:"Learn protection",title:"Recommend a protection that changes the risk",summary:"Learn to connect a control to a specific weakness or consequence.",minutes:12,html:'<section class="fm-block"><p class="fm-label">Learn</p><h2>Name the action and how it helps</h2><div class="fm-table-wrap"><table><thead><tr><th>Risk</th><th>Protection</th><th>How it changes the risk</th></tr></thead><tbody><tr><td>Stolen password</td><td>MFA</td><td>Adds a second login proof.</td></tr><tr><td>Password guessing</td><td>Long unique passwords and login-rate limits</td><td>Make guessing harder and slow repeated attempts.</td></tr><tr><td>Malware attachment</td><td>Attachment filtering, scanning, and user checks</td><td>Block or avoid suspicious files.</td></tr><tr><td>Known software weakness</td><td>Verified security update</td><td>Repairs the documented weakness.</td></tr><tr><td>Data loss</td><td>Tested offline backup</td><td>Reduces recovery time and lasting loss.</td></tr><tr><td>Unneeded personal data</td><td>Data minimization</td><td>Reduces the amount exposed.</td></tr></tbody></table></div><p class="fm-note">"Be safe" cannot be tested. A useful recommendation names who should do what and explains which part of the risk changes.</p></section>'},t("protection-practice","Protection practice","Practice security recommendations","Complete five activities by matching a protection to the stated risk.",[e("Reduce phishing success","Which recommendation is most specific?",["Use MFA and open unexpected login requests through the official site","Be careful online","Never use computers"],0,"Write an actionable protection","The first option names two actions tied to credential theft.","Choose advice that a person can follow and a teacher can check."),e("Reduce malware","Which protection best addresses unknown email attachments?",["Block risky attachment types and scan files","Use a brighter wallpaper","Rename the inbox"],0,"Match controls to malware delivery","Filtering and scanning act on the attachment path.","Choose a control where the threat enters."),e("Reduce downtime impact","Which measure helps recovery after a ransomware incident?",["Tested offline backups","One shared password","Disabling updates"],0,"Reduce impact with recovery","Tested offline backups can restore data without depending on the affected system.","Focus on recovery after the event."),e("Protect personal data","Which practice follows data minimization?",["Collect only the data needed for the stated purpose","Collect every possible detail","Publish the full dataset"],0,"Apply data minimization","Keeping less unnecessary personal data reduces exposure.","Ask whether each field is required."),e("Prioritize","Two risks have high impact. One happens often and one is rare. Which should normally be addressed first?",["The frequent high-impact risk","The rare risk only","Neither"],0,"Use probability and impact together","When impact is equal, the higher-probability risk has higher priority.","Compare the remaining axis.")]),{id:"risk-record",short:"Record risk map",title:"Record a six-risk analysis",summary:"Use the six fixed scenarios to create reconstructable risk-map evidence.",minutes:30,kind:"form",intro:r,prompt:"Record the evidence behind the six-risk map",fields:[{name:"assets",label:"R1-R6 assets: Name the affected asset for every scenario.",type:"textarea",rows:6,minlength:30},{name:"ratings",label:"R1-R6 ratings: Record low or high probability and low or high impact for every scenario.",type:"textarea",rows:7,minlength:40},{name:"evidence",label:"R1-R6 evidence: Copy one fact from each scenario that supports its rating.",type:"textarea",rows:8,minlength:60},{name:"protections",label:"R1-R6 protections: Give one specific protection for every scenario and explain how it helps.",type:"textarea",rows:9,minlength:60},{name:"priority",label:"Priority recommendation: Choose one scenario ID. Use its probability, impact, and evidence to defend why it should be handled first.",type:"textarea",rows:5,minlength:35}]},s]};i(o);
